<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import type {CallSignal} from './encryptedCrypto';
const props=defineProps<{enabled:boolean;compact?:boolean;threadId:string;name:string;send:(signal:CallSignal)=>Promise<void>}>();const emit=defineEmits<{active:[boolean]}>();
const state=ref(''),error=ref(''),muted=ref(false),audio=ref<HTMLAudioElement|null>(null);let connection:RTCPeerConnection|null=null,stream:MediaStream|null=null,remote:MediaStream|null=null,callId='',offer='',dead=false,version=0,timer:ReturnType<typeof setTimeout>|undefined,disconnectTimer:ReturnType<typeof setTimeout>|undefined;
const incoming=computed(()=>state.value==='incoming');watch(state,value=>emit('active',!!value));
function reset(){version++;if(timer)clearTimeout(timer);if(disconnectTimer)clearTimeout(disconnectTimer);connection?.close();connection=null;stream?.getTracks().forEach(t=>t.stop());stream=null;remote?.getTracks().forEach(t=>t.stop());remote=null;if(audio.value)audio.value.srcObject=null;state.value='';callId='';offer='';muted.value=false;}
async function signal(type:CallSignal['type'],sdp?:string){if(!callId)return;await props.send({type,call_id:callId,sent_at:Date.now(),...(sdp?{sdp}: {})});}
function timeout(){if(timer)clearTimeout(timer);timer=setTimeout(()=>{error.value='Private call was not answered or could not connect.';void hangup();},45000);}
async function setup(){if(!isSecureContext||!navigator.mediaDevices?.getUserMedia)throw Error('Private calls require HTTPS or localhost and microphone access.');const current=version;const response=await fetch('/communication/api/calls/ice?mode=personal',{headers:{Accept:'application/json'},cache:'no-store'});const config=await response.json();if(!response.ok)throw Error(config.message||'Call connection settings are unavailable.');const media=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(dead||current!==version){media.getTracks().forEach(t=>t.stop());throw Error('Call cancelled.');}stream=media;const pc=new RTCPeerConnection({iceServers:config.iceServers,bundlePolicy:'max-bundle'});connection=pc;for(const track of media.getTracks())pc.addTrack(track,media);pc.ontrack=event=>{remote=event.streams[0]||new MediaStream([event.track]);if(audio.value){audio.value.srcObject=remote;void audio.value.play().catch(()=>{error.value='Press Play call audio to enable sound.';});}};pc.onconnectionstatechange=()=>{if(connection!==pc)return;if(pc.connectionState==='connected'){if(timer)clearTimeout(timer);if(disconnectTimer)clearTimeout(disconnectTimer);state.value='connected';}else if(pc.connectionState==='failed'){error.value='Private call connection failed. Check the TURN server/network connection.';void hangup();}else if(pc.connectionState==='disconnected'){disconnectTimer=setTimeout(()=>void hangup(),8000);}};return pc;}
async function description(pc:RTCPeerConnection){if(pc.iceGatheringState!=='complete')await new Promise<void>((resolve,reject)=>{const timeoutId=setTimeout(()=>{pc.removeEventListener('icegatheringstatechange',changed);reject(Error('Call network setup timed out. Check your connection and TURN settings.'));},15000);function changed(){if(pc.iceGatheringState==='complete'){clearTimeout(timeoutId);pc.removeEventListener('icegatheringstatechange',changed);resolve();}}pc.addEventListener('icegatheringstatechange',changed);changed();});if(connection!==pc||!pc.localDescription)throw Error('Call cancelled.');const sdp=pc.localDescription.sdp;if(!/a=fingerprint:sha-256 /i.test(sdp)||!sdp.includes('UDP/TLS/RTP/SAVPF'))throw Error('Secure call negotiation is unavailable.');return sdp;}
async function start(){if(!props.enabled||state.value)return;error.value='';callId=crypto.randomUUID();state.value='starting';try{const pc=await setup();await pc.setLocalDescription(await pc.createOffer());const sdp=await description(pc);if(connection===pc){state.value='ringing';timeout();await signal('offer',sdp);}}catch(e){error.value=(e as Error).message;await hangup();}}
async function accept(){if(!incoming.value||!props.enabled)return;state.value='connecting';try{const pc=await setup();await pc.setRemoteDescription({type:'offer',sdp:offer});await pc.setLocalDescription(await pc.createAnswer());await signal('answer',await description(pc));if(pc.connectionState!=='connected')timeout();}catch(e){error.value=(e as Error).message;await hangup();}}
async function receive(value:CallSignal){if(dead||!props.enabled||!value||!['offer','answer','hangup'].includes(value.type)||typeof value.call_id!=='string'||typeof value.sent_at!=='number'||!Number.isFinite(value.sent_at)||Math.abs(Date.now()-value.sent_at)>90000)return;if(value.type==='offer'){if(state.value&&callId!==value.call_id){await props.send({type:'hangup',call_id:value.call_id,sent_at:Date.now()});return;}if(state.value)return;if(!value.sdp||value.sdp.length>80000||!/a=fingerprint:sha-256 /i.test(value.sdp)||!value.sdp.includes('UDP/TLS/RTP/SAVPF'))return;callId=value.call_id;offer=value.sdp;state.value='incoming';timeout();}else if(value.call_id===callId){if(value.type==='hangup'){reset();return;}if(value.type==='answer'&&connection&&state.value==='ringing'&&value.sdp&&/a=fingerprint:sha-256 /i.test(value.sdp)){state.value='connecting';try{await connection.setRemoteDescription({type:'answer',sdp:value.sdp});if(connection?.connectionState!=='connected')timeout();}catch(e){error.value=(e as Error).message;await hangup();}}}}
async function hangup(){const id=callId;reset();if(id)try{await props.send({type:'hangup',call_id:id,sent_at:Date.now()});}catch{/* Local microphone and connection are already stopped. */}}
function mute(){muted.value=!muted.value;stream?.getAudioTracks().forEach(track=>track.enabled=!muted.value);}
watch(()=>props.threadId,()=>{if(state.value)void hangup();});watch(()=>props.enabled,value=>{if(!value&&state.value)void hangup();});onBeforeUnmount(()=>{dead=true;void hangup();});defineExpose({receive,hangup});
</script>
<template><div class="encrypted-call"><button v-if="!state" type="button" class="button" :class="{compact}" :disabled="!enabled" @click="start" aria-label="Private voice call" title="Private voice call"><svg v-if="compact" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2z"/></svg><span v-else>Private voice call</span></button><div v-else class="encrypted-call-panel" role="status"><span><strong>{{incoming?'Incoming private call':state==='connected'?'Private call connected':state==='ringing'?'Calling...':'Connecting securely...'}}</strong><small>{{name}} &middot; Encrypted participant-to-participant audio</small></span><button v-if="incoming" type="button" class="comm-primary" @click="accept">Answer private call</button><button v-if="state==='connected'" type="button" class="button" @click="mute">{{muted?'Unmute':'Mute'}}</button><button type="button" class="button encrypted-hangup" @click="hangup">{{incoming?'Decline':'End call'}}</button><button v-if="state==='connected'" type="button" class="button" @click="audio?.play()">Play call audio</button></div><p v-if="error" class="encrypted-call-error" role="alert">{{error}}</p><audio ref="audio" autoplay playsinline></audio></div></template>
<style scoped>.encrypted-call-panel{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:14px;border:1px solid var(--line);border-radius:9px;background:var(--rail)}.encrypted-call-panel>span{flex:1;min-width:160px}.encrypted-call-panel strong,.encrypted-call-panel small{display:block;font-size:12px;line-height:1.6}.encrypted-call-panel small{font-size:11px;color:var(--muted)}.encrypted-hangup{color:#e45b64!important}.encrypted-call-error{font-size:12px;color:#e45b64;line-height:1.7}.encrypted-call .button{border:1px solid var(--line);border-radius:7px;padding:10px 12px;background:var(--bg);color:var(--text);font-size:12px}.encrypted-call .comm-primary{border:0;border-radius:7px;padding:10px 12px;background:var(--comm-accent,#159578);color:#fff}.encrypted-call button:disabled{opacity:.5}.encrypted-call audio{display:none}.encrypted-call .button.compact{border:0;background:transparent;padding:7px;display:grid;place-items:center;color:var(--muted)}
</style>
